import { mapGetters } from 'vuex';
import axios from '@/utils/axios';
export default {
  name: 'Footer',
  data() {
    return {
      siteStats: {
        visits: 0,
        images: 0
      }
    };
  },
  computed: {
    ...mapGetters(['userConfig']),
    thisYear() {
      return new Date().getFullYear();
    },
    disableFooter() {
      return this.userConfig?.disableFooter || false;
    },
    marqueeItems() {
      const items = [`Wenying ImgHub 已迎来 ${this.siteStats.visits.toLocaleString()} 人次`, `累计托管 ${this.siteStats.images.toLocaleString()} 张图片`];
      return [...items, ...items];
    }
  },
  mounted() {
    this.loadSiteStats();
  },
  methods: {
    async loadSiteStats() {
      try {
        const response = await axios.post('/api/siteStats');
        this.siteStats = {
          visits: Number(response.data?.visits) || 0,
          images: Number(response.data?.images) || 0
        };
      } catch (error) {
        console.warn('Failed to load site stats:', error);
      }
    }
  }
};